const body = $input.first().json.body || {};
const msg = body.message || {};
const calls = msg.toolCallList || (msg.toolWithToolCallList || []).map(t => t.toolCall) || [];
if (!calls.length) return [{ json: { tool: 'none', toolCallId: null, args: {}, error: 'no toolCallList in payload' } }];
const c = calls[0];
let args = (c.function && c.function.arguments) || c.arguments || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
return [{ json: { tool: (c.function && c.function.name) || c.name, toolCallId: c.id, args, callId: msg.call && msg.call.id } }];

// Business hours 10:00–17:00 America/New_York, Mon–Fri, 30-min grid, next 5 days, skip busy events.
const TZ = 'America/New_York';
const busy = $input.all().map(i => i.json).filter(e => e && e.start).map(e => ({
  s: new Date(e.start.dateTime || e.start.date), e: new Date((e.end && (e.end.dateTime || e.end.date)) || e.start.dateTime) }));
const toolCallId = $('Parse Tool Call').first().json.toolCallId;
const fmt = new Intl.DateTimeFormat('en-US', { timeZone: TZ, weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' });
const dayKey = new Intl.DateTimeFormat('en-US', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
const hourIn = (d) => Number(new Intl.DateTimeFormat('en-US', { timeZone: TZ, hour: 'numeric', hour12: false }).format(d));
const dowIn = (d) => new Intl.DateTimeFormat('en-US', { timeZone: TZ, weekday: 'short' }).format(d);
let t = new Date(Date.now() + 2 * 3600 * 1000); t.setUTCMinutes(t.getUTCMinutes() < 30 ? 30 : 60, 0, 0);
const end = new Date(Date.now() + 5 * 86400 * 1000);
const byDay = {};
while (t < end) {
  const h = hourIn(t), dow = dowIn(t), slotEnd = new Date(t.getTime() + 30 * 60000);
  const clash = busy.some(b => b.s < slotEnd && b.e > t);
  if (!['Sat', 'Sun'].includes(dow) && h >= 10 && h < 17 && !clash) {
    const k = dayKey.format(t);
    if (!byDay[k]) byDay[k] = { start: t.toISOString(), label: fmt.format(t) + ' Eastern' };
  }
  t = new Date(t.getTime() + 30 * 60000);
}
const offer = Object.values(byDay).slice(0, 3);
const result = offer.length
  ? `Available 20-minute slots (Eastern time): ${offer.map((s, i) => `${i + 1}) ${s.label} [slot_id=${s.start}]`).join('; ')}. Offer the caller two of these.`
  : 'No open slots in the next five days.';
return [{ json: { toolCallId, result, slots: offer } }];

