const ev = $input.first().json || {};
const p = $('Parse Tool Call').first().json;
const ok = !!(ev.id && ev.htmlLink);
let label = p.args.slot_id;
try { label = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(p.args.slot_id)) + ' Eastern'; } catch (e) {}
const result = ok ? `Booked: ${label}. A calendar invite has been sent to ${p.args.email || 'the caller'}.` : `Booking failed: ${ev.message || ev.error || 'calendar error'}. Tell the caller the team will email two time options.`;
return [{ json: { toolCallId: p.toolCallId, result, booked: ok, eventLink: ev.htmlLink || null } }];
